<x-hris.modal id="vacancy-editor" title="Vacancy and assignments"><form id="vacancy-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="position_id" label="Position" type="select" :options="$positions->mapWithKeys(fn($position)=>[$position->id=>$position->title.' ('.$position->code.')'])->all()" required/><x-hris.field name="status" type="select" :options="['Open for Application'=>'Open for Application','Filled Up'=>'Filled Up','archived'=>'Archived']" required/><x-hris.field name="description" type="textarea" class="col-12"/><x-hris.field name="closes_on" type="date"/><div class="col-md-6"><label for="vacancy-category-ids" class="form-label">Questionnaires</label><select class="form-select" id="vacancy-category-ids" name="category_ids" multiple>@foreach($categories as $category)<option value="{{ $category->id }}">{{ $category->name }}</option>@endforeach</select></div><x-hris.employee-picker name="evaluator_ids" label="Assigned evaluators" multiple/><div id="evaluator-roles" class="col-12 vstack gap-2"></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save vacancy</button></div></form></x-hris.modal>
<x-hris.modal id="category-editor" title="Exam category"><form id="category-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="name" required/><x-hris.field name="exam_type" required/><x-hris.field name="time_limit" label="Time limit (minutes)" type="number" min="1" max="480" required/><div class="col-12 form-check ms-2"><input id="category-archive" name="archive" type="checkbox" class="form-check-input"><label for="category-archive" class="form-check-label">Archive category</label></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save category</button></div></form></x-hris.modal>
