<x-hris.modal id="application-review" title="Review application"><form id="application-review-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><x-hris.field name="status" type="select" :options="array_combine(['pending application','for assessment','hired','short listed','failed'],['Pending application','For assessment','Hired','Short listed','Failed'])" required/><x-hris.field name="remark" type="textarea"/><div class="form-check mt-3"><input id="application-allow-test" name="allow_test" type="checkbox" class="form-check-input"><label for="application-allow-test" class="form-check-label">Enable assigned examinations (assessment / short listed applications)</label></div></div><div class="modal-footer"><button class="btn btn-primary">Save review</button></div></form></x-hris.modal>
