@push('scripts')<script>
document.addEventListener('hris:ready',()=>{
 const vacancies=document.querySelector('#vacancies-table'),applications=document.querySelector('#applications-table'),bank=document.querySelector('#exam-bank-table'),vacancyForm=document.querySelector('#vacancy-form'),categoryForm=document.querySelector('#category-form'),questionForm=document.querySelector('#question-form'),review=document.querySelector('#application-review-form');
 const refresh=()=>{vacancies.table.load();applications.table.load();bank?.table.load();document.querySelector('#applicant-documents-table')?.table.load()};
 for(const id of ['recruitment-upload-form','applicant-profile-form','application-review-form']){const form=document.getElementById(id);if(form)HRIS.bindForm(form,{success:refresh})}
 applications.addEventListener('table:loaded',()=>{const select=document.querySelector('#document-application');select.replaceChildren(new Option('My general applicant requirements',''));for(const row of applications.table.rows.values())select.append(new Option(`${row.vacancy.position.title} · ${row.applicant.name}`,row.id))});
 document.querySelector('#applicant-documents-table')?.addEventListener('table:action',({detail:{row}})=>window.open(`/files/${row.private_file_id}`,'_blank','noopener'));
 function roles(values={}){const holder=document.querySelector('#evaluator-roles');holder.replaceChildren();for(const option of vacancyForm.elements.evaluator_ids.selectedOptions){const label=document.createElement('label'),input=document.createElement('input');label.className='form-label';label.textContent=`${option.textContent} — evaluator role`;input.className='form-control';input.dataset.evaluator=option.value;input.value=values[option.value]||'Evaluator';input.required=true;label.append(input);holder.append(label)}}
 if(vacancyForm){HRIS.bindForm(vacancyForm,{prepare:body=>{body.evaluators=[...document.querySelectorAll('[data-evaluator]')].map(input=>({user_id:Number(input.dataset.evaluator),role:input.value}));delete body.evaluator_ids},success:refresh});vacancyForm.elements.evaluator_ids.addEventListener('change',()=>roles(Object.fromEntries([...document.querySelectorAll('[data-evaluator]')].map(input=>[input.dataset.evaluator,input.value]))));document.querySelector('#new-vacancy').onclick=()=>{HRIS.fillForm(vacancyForm,{status:'Open for Application'});roles();vacancyForm.dataset.endpoint='/hr/recruitment/vacancies';vacancyForm.dataset.method='POST';HRIS.openModal('vacancy-editor')};HRIS.bindForm(categoryForm,{success:(result,body)=>{refresh();const select=document.querySelector('#vacancy-category-ids');let option=[...select.options].find(o=>o.value===String(result.id));if(!option){option=new Option(body.name,result.id);select.append(option)}option.textContent=body.name}});document.querySelector('#new-category').onclick=()=>{HRIS.fillForm(categoryForm,{});categoryForm.dataset.endpoint='/hr/recruitment/categories';categoryForm.dataset.method='POST';HRIS.openModal('category-editor')};HRIS.bindForm(questionForm,{success:refresh})}
 vacancies.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='apply'){if(await HRIS.confirm(`Apply for ${row.position.title}?`)){HRIS.feedback((await HRIS.request(`/careers/vacancies/${row.id}/apply`,{method:'POST',body:{}})).message);refresh()}return}const picker=vacancyForm.elements.evaluator_ids;for(const evaluator of row.evaluators||[])if(![...picker.options].some(o=>o.value===String(evaluator.id)))picker.append(new Option(evaluator.name,evaluator.id));HRIS.fillForm(vacancyForm,{...row,category_ids:row.categories.map(c=>c.id),evaluator_ids:(row.evaluators||[]).map(e=>e.id)});roles(Object.fromEntries((row.evaluators||[]).map(e=>[e.id,e.pivot.role])));vacancyForm.dataset.endpoint=`/hr/recruitment/vacancies/${row.id}`;vacancyForm.dataset.method='PUT';HRIS.openModal('vacancy-editor')}catch(error){HRIS.feedback(error.message,true)}});
 applications.addEventListener('table:action',({detail:{action,row}})=>{if(action==='report'){window.open(`/recruitment/applications/${row.id}/report`,'_blank','noopener');return}if(action==='review'){HRIS.fillForm(review,row);review.dataset.endpoint=`/hr/recruitment/applications/${row.id}/review`;HRIS.openModal('application-review');return}document.querySelector('#application-info').textContent=`${row.applicant.name} · ${row.status} · ${row.remark||''}\n${(row.history||[]).map(entry=>`${entry.status} — ${entry.actor?.name||"Recorded actor"}${entry.reason?`: ${entry.reason}`:""}`).join("\n")}`;const actions=document.querySelector('#application-actions'),files=document.querySelector('#application-files');actions.replaceChildren();files.replaceChildren();if(@json(auth()->user()->role==='applicant')&&row.allow_test){for(const category of row.vacancy.categories){const button=document.createElement('button');button.className='btn btn-outline-primary';button.textContent=`Start / resume ${category.name} (${category.time_limit} minutes)`;button.onclick=async()=>{button.disabled=true;try{if(await HRIS.confirm('Start or resume this examination? The server timer cannot be reset.')){const result=await HRIS.request(`/careers/applications/${row.id}/exams/${category.id}/start`,{method:'POST',body:{}});window.location.assign(result.url)}}catch(error){HRIS.feedback(error.message,true)}finally{button.disabled=false}};actions.append(button)}}else if(!@json(auth()->user()->role==='applicant')){const link=document.createElement('a');link.href=`/recruitment/applications/${row.id}/report`;link.textContent='Print answer report';link.target='_blank';link.rel='noopener';actions.append(link)}for(const documentRecord of [...(row.documents||[]),...(row.general_documents||[])]){const link=document.createElement('a');link.href=`/files/${documentRecord.private_file_id}`;link.textContent=`${documentRecord.document_type} (${documentRecord.side})`;files.append(link)}HRIS.openModal('application-details')});
 function addChoice(choice={}){const holder=document.querySelector('#question-choices'),index=holder.children.length,group=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),image=document.createElement('input');label.className='form-label d-block';label.textContent=`Choice ${index+1}`;input.className='form-control';input.name=`choices[${index}][text]`;input.value=choice.text||'';input.required=true;image.type='file';image.accept='.jpg,.jpeg,.png';image.name=`choices[${index}][image]`;image.className='form-control mt-2';image.setAttribute('aria-label',`Optional image for choice ${index+1}`);label.append(input);group.append(label,image);holder.append(group)}
 function editQuestion(category,question=null){HRIS.fillForm(questionForm,question||{question_type:1});document.querySelector('#question-choices').replaceChildren();for(const choice of question?.choices||[])addChoice(choice);questionForm.dataset.endpoint=`/hr/recruitment/categories/${category.id}/questions${question?`/${question.id}`:''}`;HRIS.openModal('question-editor')}
 document.querySelector('#add-exam-choice')?.addEventListener('click',()=>addChoice());questionForm?.elements.question_type.addEventListener('change',()=>{const disabled=questionForm.elements.question_type.value!=='1';document.querySelectorAll('#question-choices input').forEach(input=>input.disabled=disabled);document.querySelector('#add-exam-choice').disabled=disabled});
 bank?.addEventListener('table:action',({detail:{action,row}})=>{if(action==='edit'){HRIS.fillForm(categoryForm,{...row,archive:!!row.archived_at});categoryForm.dataset.endpoint=`/hr/recruitment/categories/${row.id}`;categoryForm.dataset.method='PUT';HRIS.openModal('category-editor')}else if(action==='add-question')editQuestion(row);else{const list=document.querySelector('#question-items');list.replaceChildren();for(const question of row.questions){const button=document.createElement('button');button.className='btn btn-outline-secondary text-start';button.textContent=`${question.question_type}. ${question.question}`;button.onclick=()=>editQuestion(row,question);list.append(button)}HRIS.openModal('question-list')}});
});
</script>@endpush
